package com.univalle.dogapp.model

import androidx.room.Entity
import androidx.room.PrimaryKey
import java.io.Serializable

/**
 * A pet appointment stored with Room.
 * The autogenerated id is the attention turn shown in Home (HU-02) and Detail (HU-04).
 */
@Entity
data class Appointment(
    @PrimaryKey(autoGenerate = true)
    val id: Int = 0,
    val petName: String,
    val breed: String,
    val ownerName: String,
    val phone: String,
    val symptom: String,
    /** URL of a random image of the breed, from the Dog API. */
    val imageUrl: String
) : Serializable
